package claudecode

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

const (
	pruneRetention = 30 * 24 * time.Hour

	idExpiredA = "11111111-1111-4111-8111-111111111111"
	idExpiredB = "22222222-2222-4222-8222-222222222222"
	idSession  = "33333333-3333-4333-8333-333333333333"
	idFresh    = "44444444-4444-4444-8444-444444444444"
	idLink     = "55555555-5555-4555-8555-555555555555"
	idNested   = "66666666-6666-4666-8666-666666666666"
)

var pruneNow = time.Date(2026, 11, 19, 12, 0, 0, 0, time.UTC)

// pruneFile writes body to dir/name, creating dir, and sets its modification time to age before pruneNow.
func pruneFile(t *testing.T, dir, name, body string, age time.Duration) string {
	t.Helper()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	p := filepath.Join(dir, name)
	if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	mt := pruneNow.Add(-age)
	if err := os.Chtimes(p, mt, mt); err != nil {
		t.Fatal(err)
	}
	return p
}

func mustExist(t *testing.T, path, body string) {
	t.Helper()
	got, err := os.ReadFile(path)
	if err != nil {
		t.Errorf("%s should remain: %v", path, err)
		return
	}
	if string(got) != body {
		t.Errorf("%s content = %q, want %q", path, got, body)
	}
}

func TestPruneTranscriptsRemovesExpiredAndReportsCountAndBytes(t *testing.T) {
	config := t.TempDir()
	projects := filepath.Join(config, "projects")
	bodyA := "{\"type\":\"user\",\"text\":\"first expired transcript\"}\n"
	bodyB := "{\"type\":\"user\",\"text\":\"second, longer expired transcript in another folder\"}\n"
	a := pruneFile(t, filepath.Join(projects, "-work-app"), idExpiredA+".jsonl", bodyA, 60*24*time.Hour)
	b := pruneFile(t, filepath.Join(projects, "-work-lib"), idExpiredB+".jsonl", bodyB, 45*24*time.Hour)

	got := pruneTranscripts(config, pruneNow, pruneRetention, "unrelated-session")

	for _, p := range []string{a, b} {
		if _, err := os.Lstat(p); !os.IsNotExist(err) {
			t.Errorf("expired transcript %s should be removed, Lstat error = %v", p, err)
		}
	}
	want := transcriptReport{removed: 2, removedBytes: int64(len(bodyA) + len(bodyB))}
	if got != want {
		t.Errorf("report = %+v, want %+v", got, want)
	}
}

func TestPruneTranscriptsKeepsCurrentFreshAndNonUUIDFiles(t *testing.T) {
	config := t.TempDir()
	folder := filepath.Join(config, "projects", "-work-app")
	old := 60 * 24 * time.Hour
	files := map[string]string{
		idSession + ".jsonl": "current session, expired by age\n",
		idFresh + ".jsonl":   "fresh transcript\n",
		"notes.jsonl":        "expired but not a UUID transcript\n",
	}
	ages := map[string]time.Duration{idSession + ".jsonl": old, idFresh + ".jsonl": time.Hour, "notes.jsonl": old}
	for name, body := range files {
		pruneFile(t, folder, name, body, ages[name])
	}

	got := pruneTranscripts(config, pruneNow, pruneRetention, idSession)

	for name, body := range files {
		mustExist(t, filepath.Join(folder, name), body)
	}
	if want := (transcriptReport{kept: 1}); got != want {
		t.Errorf("report = %+v, want %+v", got, want)
	}
}

func TestPruneTranscriptsDoesNotFollowOrRemoveSymlinks(t *testing.T) {
	config := t.TempDir()
	folder := filepath.Join(config, "projects", "-work-app")
	body := "expired transcript below the working-directory folder\n"
	target := pruneFile(t, filepath.Join(folder, "subagents"), idNested+".jsonl", body, 60*24*time.Hour)
	link := filepath.Join(folder, idLink+".jsonl")
	if err := os.Symlink(filepath.Join("subagents", idNested+".jsonl"), link); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}

	got := pruneTranscripts(config, pruneNow, pruneRetention, "unrelated-session")

	fi, err := os.Lstat(link)
	if err != nil {
		t.Fatalf("symlink should remain: %v", err)
	}
	if fi.Mode()&os.ModeSymlink == 0 {
		t.Errorf("%s mode = %v, want a symlink", link, fi.Mode())
	}
	mustExist(t, target, body)
	if want := (transcriptReport{}); got != want {
		t.Errorf("report = %+v, want %+v", got, want)
	}
}

